/// <summary>
/// PaffH 06.08.25
/// last modified: PaffH 18.08.25
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(NDXBVEMailRequestState), DataEventType::ModifiedField)]
public static void NDXBVEMailRequestState_onModifiedField(Common sender, DataEventArgs e)
{
    ModifyFieldEventArgs eventArgs = e;
    NDXBVEMailRequestState nDXBVEMailRequestState = sender as NDXBVEMailRequestState;
    switch (eventArgs.parmFieldId())
    {
        case fieldNum(NDXBVEMailRequestState, BVEmailRequestProcessingState):
            nDXBVEMailRequestState.StatusChangedBy = curUserId();
            nDXBVEMailRequestState.StatusChangedDateTime = DateTimeUtil::utcNow();
            break;
        case fieldNum(NDXBVEMailRequestState, CustAccountManualSelected):
            nDXBVEMailRequestState.RoleForBuildingProject = NDXRoleForBuildingProject::Customer;
            nDXBVEMailRequestState.CustomerChangedManual = NoYes::Yes;
            break;
        case fieldNum(NDXBVEMailRequestState, smmBusRelAccountManualSelected):
            nDXBVEMailRequestState.RoleForBuildingProject = NDXRoleForBuildingProject::BusRel;
            nDXBVEMailRequestState.BusRelChangedManual = NoYes::Yes;
            break;
    }
}

/// <summary>
/// PaffH 06.08.25
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(NDXBVEMailRequestState), DataEventType::Updating),
    SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXBVEMailRequestState_onUpdating(Common sender, DataEventArgs e)
{
    NDXBVEMailRequestState nDXBVEMailRequestState = sender as NDXBVEMailRequestState;
    if (nDXBVEMailRequestState.orig().BVEmailRequestProcessingState
        != nDXBVEMailRequestState.BVEmailRequestProcessingState)
    {
        NDXBVEMailRequestStateChangeLog::insertLog(nDXBVEMailRequestState);
    }
}
